package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"slices"

	"github.com/openai/openai-go/v3"
)

// Tool is a function that the model can ask the program to execute.
type Tool struct {
	Name        string
	Description string
	// Parameters is the JSON schema of the tool's arguments.
	Parameters openai.FunctionParameters
	// Run executes the tool. arguments is the JSON object generated by the
	// model, still encoded as a string.
	Run func(ctx context.Context, arguments string) (string, error)
}

// Spec returns the tool's specification in the form advertised to the model.
func (t Tool) Spec() openai.ChatCompletionToolUnionParam {
	return openai.ChatCompletionFunctionTool(openai.FunctionDefinitionParam{
		Name:        t.Name,
		Description: openai.String(t.Description),
		Parameters:  t.Parameters,
	})
}

// Toolbox is a set of tools offered to the model.
type Toolbox []Tool

// baseToolbox returns the tools that act on the project, among which the LSP
// tool if a language server is connected. They are all that a subagent gets.
func baseToolbox(lsp *languageServer) Toolbox {
	toolbox := Toolbox{readTool, writeTool, bashTool}
	if lsp != nil {
		toolbox = append(toolbox, newLSPTool(lsp))
	}
	return toolbox
}

// newToolbox returns the tools offered to the main agent: the base tools and,
// if the project has skills, the tool that uses them, which runs the skills
// that ask for a subagent with fork.
func newToolbox(base Toolbox, skills []Skill, fork forkFunc) Toolbox {
	toolbox := slices.Clone(base)
	if len(skills) > 0 {
		toolbox = append(toolbox, newSkillTool(skills, fork))
	}
	return toolbox
}

// Specs returns the specification of every tool, to be sent with each request.
func (tb Toolbox) Specs() []openai.ChatCompletionToolUnionParam {
	specs := make([]openai.ChatCompletionToolUnionParam, len(tb))
	for i, tool := range tb {
		specs[i] = tool.Spec()
	}
	return specs
}

// Call executes the named tool with the JSON-encoded arguments generated by
// the model and returns the tool's result.
func (tb Toolbox) Call(ctx context.Context, name, arguments string) (string, error) {
	for _, tool := range tb {
		if tool.Name == name {
			return tool.Run(ctx, arguments)
		}
	}
	return "", fmt.Errorf("unknown tool %q", name)
}

// decodeArguments parses the JSON-encoded arguments of a tool call.
func decodeArguments(arguments string, into any) error {
	if err := json.Unmarshal([]byte(arguments), into); err != nil {
		return fmt.Errorf("invalid arguments: %w", err)
	}
	return nil
}

// readTool reads a file and returns its contents.
var readTool = Tool{
	Name:        "Read",
	Description: "Read and return the contents of a file",
	Parameters: openai.FunctionParameters{
		"type": "object",
		"properties": map[string]any{
			"file_path": map[string]any{
				"type":        "string",
				"description": "The path to the file to read",
			},
		},
		"required": []string{"file_path"},
	},
	Run: func(_ context.Context, arguments string) (string, error) {
		var args struct {
			FilePath string `json:"file_path"`
		}
		if err := decodeArguments(arguments, &args); err != nil {
			return "", err
		}
		if args.FilePath == "" {
			return "", errors.New("file_path is required")
		}
		contents, err := os.ReadFile(args.FilePath)
		if err != nil {
			return "", err
		}
		return string(contents), nil
	},
}

// writeTool writes content to a file, creating the file (and any missing
// parent directory) or overwriting it if it already exists.
var writeTool = Tool{
	Name:        "Write",
	Description: "Write content to a file",
	Parameters: openai.FunctionParameters{
		"type":     "object",
		"required": []string{"file_path", "content"},
		"properties": map[string]any{
			"file_path": map[string]any{
				"type":        "string",
				"description": "The path of the file to write to",
			},
			"content": map[string]any{
				"type":        "string",
				"description": "The content to write to the file",
			},
		},
	},
	Run: func(_ context.Context, arguments string) (string, error) {
		var args struct {
			FilePath string `json:"file_path"`
			// A pointer tells a missing content apart from an empty one, which
			// is a legitimate way to create an empty file.
			Content *string `json:"content"`
		}
		if err := decodeArguments(arguments, &args); err != nil {
			return "", err
		}
		if args.FilePath == "" {
			return "", errors.New("file_path is required")
		}
		if args.Content == nil {
			return "", errors.New("content is required")
		}
		if err := os.MkdirAll(filepath.Dir(args.FilePath), 0o755); err != nil {
			return "", err
		}
		if err := os.WriteFile(args.FilePath, []byte(*args.Content), 0o644); err != nil {
			return "", err
		}
		return fmt.Sprintf("Wrote %d bytes to %s", len(*args.Content), args.FilePath), nil
	},
}
